<script lang="ts">
  import type {Database,DatabaseViewConfig,Page,PropertyValue} from "@/features/notion-ui/variants/database/types"; import PropertyCell from "../PropertyCell.svelte"; import {visibleProps} from "../../lib/view-core";
  let {mode,db,view,rows,readOnly=false,pages=[],onRowUpdate,onOpenRow}= $props<{mode:"list"|"gallery"|"feed";db:Database;view:DatabaseViewConfig;rows:Page[];readOnly?:boolean;pages?:Page[];onRowUpdate?:(r:string,p:string,v:PropertyValue)=>void;onOpenRow?:(id:string)=>void}>();
